        async function expectedNativePageRect(){
          const css=await ordinaryChrome.executeJavaScript('(()=>{const r=document.getElementById("page-area").getBoundingClientRect();return {x:Math.ceil(r.x+1),y:Math.ceil(r.y+1),width:Math.floor(r.width-2),height:Math.floor(r.height-2),toolbarBottom:document.getElementById("toolbar").getBoundingClientRect().bottom}})()');
          const zoom=ordinaryChrome.getZoomFactor(),[width,height]=ordinary.window.getContentSize();
          const x=Math.min(width,Math.max(0,Math.round(css.x*zoom))),y=Math.min(height,Math.max(0,Math.round(css.y*zoom)));
          return {bounds:{x,y,width:Math.max(0,Math.min(width-x,Math.round(css.width*zoom))),height:Math.max(0,Math.min(height-y,Math.round(css.height*zoom)))},toolbarBottom:Math.round(css.toolbarBottom*zoom)};
        }
